mapper.sql:
where r.deleted = 0
  and m.deleted = 0
  and r.receiver_subject = #{receiverSubject}
  and r.receiver_user_id = #{receiverUserId}

    and r.read_status = #{query.readStatus}


    and m.message_type = #{query.messageType}


    and m.title like concat('%', #{query.title}, '%')

mapper.select:
select

from notif_message_receiver r
inner join notif_message m on m.id = r.message_id
where r.deleted = 0
  and m.deleted = 0
  and r.receiver_subject = #{receiverSubject}
  and r.receiver_user_id = #{receiverUserId}
order by r.id desc
limit #{limit}
